package com.blockchain.proxy.contract;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.security.*;
import java.util.concurrent.*;
import java.util.logging.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/**
 * SmartContractExecutor handles contract state persistence
 * behind a reverse proxy that manages TLS termination.
 * State snapshots are written atomically to prevent corruption
 * during concurrent block validation.
 */
public class SmartContractExecutor {

    private static final Logger LOG = Logger.getLogger(SmartContractExecutor.class.getName());
    private static final String STATE_DIR = "/var/lib/blockchain/state";
    private static final int SNAPSHOT_RETENTION = 128;

    private final ConcurrentHashMap<String, byte[]> contractState;
    private final ExecutorService validationPool;
    private final SecureRandom secureRandom;
    private final Path stateDirectory;

    public SmartContractExecutor(Path stateDir) throws NoSuchAlgorithmException {
        this.stateDirectory = stateDir;
        this.contractState = new ConcurrentHashMap<>();
        this.validationPool = Executors.newFixedThreadPool(4);
        this.secureRandom = SecureRandom.getInstanceStrong();
    }

    /**
     * Persists contract state snapshot during block finalization.
     * Uses atomic file operations to prevent partial writes.
     */
    public Path persistStateSnapshot(String contractId, byte[] stateData, long blockHeight)
            throws IOException, GeneralSecurityException {

        validateContractId(contractId);
        byte[] encrypted = encryptState(stateData, contractId);

        // Create snapshot file with restricted permissions
        Path snapshotFile = createSecureSnapshotFile(contractId, blockHeight);

        // Atomic write via temp file + rename
        Path tempFile = createTempForAtomicWrite(snapshotFile);
        try {
            Files.write(tempFile, encrypted, StandardOpenOption.WRITE);
            Files.move(tempFile, snapshotFile, StandardCopyOption.ATOMIC_MOVE);
            LOG.info("Persisted state for contract " + contractId + " at block " + blockHeight);
        } catch (IOException e) {
            Files.deleteIfExists(tempFile);
            throw e;
        }

        contractState.put(contractId, stateData);
        return snapshotFile;
    }

    /**
     * Creates a temporary file for atomic write operations.
     * The temp file is created in the same directory as the target
     * to ensure atomic rename works (same filesystem).
     */
    private Path createTempForAtomicWrite(Path targetFile) throws IOException {
        Path parentDir = targetFile.getParent();
        // Generate unique suffix using contract execution context
        String prefix = ".tmp_" + targetFile.getFileName().toString();

        // Create temp file with owner-only permissions using NIO2
        // This avoids the insecure default permissions of File.createTempFile
        Set<PosixFilePermission> ownerOnly = PosixFilePermissions.fromString("rw-------");
        FileAttribute<Set<PosixFilePermission>> attr =
            PosixFilePermissions.asFileAttribute(ownerOnly);
        return Files.createTempFile(parentDir, prefix, ".state", attr);
    }

    private Path createSecureSnapshotFile(String contractId, long blockHeight) throws IOException {
        String filename = String.format("snapshot_%s_%016x.enc", contractId, blockHeight);
        Path filePath = stateDirectory.resolve(filename);

        // Ensure parent directory exists with restricted permissions
        if (!Files.exists(filePath.getParent())) {
            Files.createDirectories(filePath.getParent(),
                PosixFilePermissions.asFileAttribute(
                    PosixFilePermissions.fromString("rwx------")));
        }

        return filePath;
    }

    private byte[] encryptState(byte[] data, String contractId) throws GeneralSecurityException {
        byte[] keyMaterial = deriveKey(contractId);
        SecretKeySpec keySpec = new SecretKeySpec(keyMaterial, "AES");
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        byte[] iv = new byte[12];
        secureRandom.nextBytes(iv);
        GCMParameterSpec gcmSpec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec);
        byte[] ciphertext = cipher.doFinal(data);

        // Prepend IV to ciphertext
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }

    private byte[] deriveKey(String contractId) throws GeneralSecurityException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        // Use an explicit charset to ensure deterministic key material across environments
        byte[] seed = (contractId + "_state_key_v2").getBytes(StandardCharsets.UTF_8);
        return digest.digest(seed);
    }

    private void validateContractId(String contractId) {
        if (contractId == null || !contractId.matches("^[a-f0-9]{40}$")) {
            throw new IllegalArgumentException("Invalid contract ID format");
        }
    }

    /**
     * Validates block state transitions by comparing snapshots.
     * Called by the reverse proxy's validation endpoint.
     */
    public CompletableFuture<Boolean> validateStateTransition(
            String contractId, long fromBlock, long toBlock) {

        return CompletableFuture.supplyAsync(() -> {
            try {
                Path fromSnapshot = stateDirectory.resolve(
                    String.format("snapshot_%s_%016x.enc", contractId, fromBlock));
                Path toSnapshot = stateDirectory.resolve(
                    String.format("snapshot_%s_%016x.enc", contractId, toBlock));

                if (!Files.exists(fromSnapshot) || !Files.exists(toSnapshot)) {
                    return false;
                }

                byte[] fromData = Files.readAllBytes(fromSnapshot);
                byte[] toData = Files.readAllBytes(toSnapshot);

                return verifyTransitionIntegrity(fromData, toData, contractId);
            } catch (Exception e) {
                LOG.warning("Validation failed: " + e.getMessage());
                return false;
            }
        }, validationPool);
    }

    private boolean verifyTransitionIntegrity(byte[] from, byte[] to, String contractId)
            throws GeneralSecurityException {
        // Verify both snapshots decrypt successfully with the contract key
        byte[] keyMaterial = deriveKey(contractId);
        SecretKeySpec keySpec = new SecretKeySpec(keyMaterial, "AES");

        decryptAndVerify(from, keySpec);
        decryptAndVerify(to, keySpec);
        return true;
    }

    private byte[] decryptAndVerify(byte[] encData, SecretKeySpec keySpec)
            throws GeneralSecurityException {
        if (encData.length < 12) throw new GeneralSecurityException("Invalid data");
        byte[] iv = new byte[12];
        System.arraycopy(encData, 0, iv, 0, 12);
        byte[] ciphertext = new byte[encData.length - 12];
        System.arraycopy(encData, 12, ciphertext, 0, ciphertext.length);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        GCMParameterSpec gcmSpec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec);
        return cipher.doFinal(ciphertext);
    }

    public void shutdown() {
        validationPool.shutdown();
    }
}
